171→// readAndParseTranscript reads and parses a Kiro transcript file.
172→// Returns errTranscriptEmpty if the file doesn't exist or is empty.
173→func readAndParseTranscript(path string) (*kiroTranscript, error) {
174→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
175→	if err != nil {
176→		if os.IsNotExist(err) {
177→			return nil, errTranscriptEmpty
178→		}
179→		return nil, fmt.Errorf("reading transcript: %w", err)
180→	}
181→	if len(data) == 0 {
182→		return nil, errTranscriptEmpty
183→	}
184→	t, err := parseTranscript(data)
185→	if err != nil {
186→		return nil, fmt.Errorf("parsing transcript: %w", err)
187→	}
188→	return t, nil
189→}
