191→// GetTranscriptPosition returns the number of history entries in a Kiro transcript.
192→// Kiro uses JSON format with paired user+assistant history entries, so position
193→// is the entry count. Returns 0 if the file doesn't exist, is empty, or is a
194→// placeholder "{}".
195→func (k *KiroAgent) GetTranscriptPosition(path string) (int, error) {
196→	if path == "" {
197→		return 0, nil
198→	}
199→	t, err := readAndParseTranscript(path)
200→	if errors.Is(err, errTranscriptEmpty) {
201→		return 0, nil
202→	}
203→	if err != nil {
204→		return 0, err
205→	}
206→	return len(t.History), nil
207→}
