209→// ExtractModifiedFilesFromOffset extracts files modified since a given history index.
210→// For Kiro (JSON format), offset is the starting history entry index.
211→func (k *KiroAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
212→	if path == "" {
213→		return nil, 0, nil
214→	}
215→	t, parseErr := readAndParseTranscript(path)
216→	if errors.Is(parseErr, errTranscriptEmpty) {
217→		return nil, 0, nil
218→	}
219→	if parseErr != nil {
220→		return nil, 0, parseErr
221→	}
222→
223→	totalEntries := len(t.History)
224→	if startOffset >= totalEntries {
225→		return nil, totalEntries, nil
226→	}
227→
228→	modifiedFiles := extractModifiedFilesFromHistory(t.History[startOffset:])
229→	return modifiedFiles, totalEntries, nil
230→}
