265→// --- SQLite session resolution ---
266→
267→// dbPath returns the path to Kiro's SQLite database.
268→func dbPath() (string, error) {
269→	home, err := os.UserHomeDir()
270→	if err != nil {
271→		return "", fmt.Errorf("failed to get home directory: %w", err)
272→	}
273→	switch runtime.GOOS {
274→	case "darwin":
275→		return filepath.Join(home, "Library", "Application Support", "kiro-cli", "data.sqlite3"), nil
276→	default: // linux
277→		return filepath.Join(home, ".local", "share", "kiro-cli", "data.sqlite3"), nil
278→	}
279→}
280→
281→// querySessionID queries the SQLite database for the most recent conversation ID
282→// associated with the given CWD.
283→func (k *KiroAgent) querySessionID(ctx context.Context, cwd string) (string, error) {
284→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
285→		return "mock-session-id", nil
286→	}
287→
288→	db, err := dbPath()
289→	if err != nil {
290→		return "", err
291→	}
292→	if _, err := os.Stat(db); err != nil {
293→		return "", fmt.Errorf("kiro database not found at %s: %w", db, err)
294→	}
295→
296→	query := fmt.Sprintf(
297→		"SELECT json_extract(value, '$.conversation_id') FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
298→		escapeSQLString(cwd),
299→	)
300→
301→	cmd := exec.CommandContext(ctx, "sqlite3", "-json", db, query)
302→	out, err := cmd.Output()
303→	if err != nil {
304→		logging.Warn(ctx, "kiro: sqlite3 query failed", "err", err, "cwd", cwd)
305→		return "", fmt.Errorf("sqlite3 query failed: %w", err)
306→	}
307→
308→	result := strings.TrimSpace(string(out))
309→	if result == "" || result == "[]" {
310→		return "", nil
311→	}
312→
313→	// sqlite3 -json returns an array of objects
314→	var rows []map[string]string
315→	if err := json.Unmarshal([]byte(result), &rows); err != nil {
316→		return "", fmt.Errorf("failed to parse sqlite3 output: %w", err)
317→	}
318→	if len(rows) == 0 {
319→		return "", nil
320→	}
321→
322→	// The column name from json_extract
323→	for _, v := range rows[0] {
324→		return v, nil
325→	}
326→	return "", nil
327→}
328→
329→// ensureCachedTranscript fetches the conversation from SQLite and caches it
330→// to .entire/tmp/<sessionID>.json. Returns the cache file path.
331→func (k *KiroAgent) ensureCachedTranscript(ctx context.Context, cwd, sessionID string) (string, error) {
332→	repoRoot, err := paths.WorktreeRoot(ctx)
333→	if err != nil {
334→		repoRoot = cwd
335→	}
336→
337→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
338→	cachePath := filepath.Join(cacheDir, sessionID+".json")
339→
340→	// Fetch fresh transcript from SQLite on every call (transcript grows during session)
341→	if os.Getenv("ENTIRE_TEST_KIRO_MOCK_DB") == "1" {
342→		// In test mode, return the expected cache path without hitting SQLite.
343→		return cachePath, nil
344→	}
345→
346→	db, err := dbPath()
347→	if err != nil {
348→		return "", err
349→	}
350→
351→	query := fmt.Sprintf(
352→		"SELECT value FROM conversations_v2 WHERE key = '%s' ORDER BY updated_at DESC LIMIT 1",
353→		escapeSQLString(cwd),
354→	)
355→
356→	cmd := exec.CommandContext(ctx, "sqlite3", db, query)
357→	out, err := cmd.Output()
358→	if err != nil {
359→		return "", fmt.Errorf("sqlite3 transcript query failed: %w", err)
360→	}
361→
362→	transcript := strings.TrimSpace(string(out))
363→	if transcript == "" {
364→		return "", errors.New("no transcript found")
365→	}
366→
367→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
368→		return "", fmt.Errorf("failed to create cache dir: %w", err)
369→	}
370→
371→	if err := os.WriteFile(cachePath, []byte(transcript), 0o600); err != nil {
372→		return "", fmt.Errorf("failed to write cached transcript: %w", err)
373→	}
374→
375→	return cachePath, nil
376→}
