378→// --- IDE transcript discovery ---
379→
380→// ideWorkspaceSessionsDir returns the directory where the Kiro IDE stores
381→// session files for the given working directory. The directory is derived from
382→// the base64-encoded CWD.
383→func ideWorkspaceSessionsDir(cwd string) (string, error) {
384→	home, err := os.UserHomeDir()
385→	if err != nil {
386→		return "", fmt.Errorf("failed to get home directory: %w", err)
387→	}
388→
389→	encoded := base64.StdEncoding.EncodeToString([]byte(cwd))
390→
391→	var baseDir string
392→	switch runtime.GOOS {
393→	case "darwin":
394→		baseDir = filepath.Join(home, "Library", "Application Support", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
395→	default: // linux
396→		baseDir = filepath.Join(home, ".config", "Kiro", "User", "globalStorage", "kiro.kiroagent", "workspace-sessions")
397→	}
398→
399→	return filepath.Join(baseDir, encoded), nil
400→}
401→
402→// ensureIDETranscript looks for the most recent Kiro IDE session transcript
403→// for the given CWD and copies it to .entire/tmp/<sessionID>.json.
404→// Returns the cache path on success, or empty string if no transcript is found.
405→func (k *KiroAgent) ensureIDETranscript(ctx context.Context, cwd, sessionID string) (string, error) {
406→	sessDir, err := ideWorkspaceSessionsDir(cwd)
407→	if err != nil {
408→		return "", err
409→	}
410→
411→	// Read the sessions.json index.
412→	indexPath := filepath.Join(sessDir, "sessions.json")
413→	indexData, err := os.ReadFile(indexPath) //nolint:gosec // Controlled path from IDE storage
414→	if err != nil {
415→		logging.Debug(ctx, "kiro: IDE sessions.json not found", "path", indexPath, "err", err)
416→		return "", fmt.Errorf("IDE sessions.json not found: %w", err)
417→	}
418→
419→	var sessions []kiroIDESessionEntry
420→	if err := json.Unmarshal(indexData, &sessions); err != nil {
421→		return "", fmt.Errorf("failed to parse IDE sessions.json: %w", err)
422→	}
423→
424→	if len(sessions) == 0 {
425→		return "", errors.New("no IDE sessions found")
426→	}
427→
428→	// Sort by dateCreated descending to find the most recent session.
429→	sort.Slice(sessions, func(i, j int) bool {
430→		return sessions[i].DateCreated > sessions[j].DateCreated
431→	})
432→
433→	// Read the most recent session's transcript.
434→	latestSession := sessions[0]
435→	transcriptPath := filepath.Join(sessDir, latestSession.SessionID+".json")
436→	transcriptData, err := os.ReadFile(transcriptPath) //nolint:gosec // Controlled path from IDE storage
437→	if err != nil {
438→		return "", fmt.Errorf("failed to read IDE transcript %s: %w", transcriptPath, err)
439→	}
440→
441→	// Cache the transcript under our session ID.
442→	repoRoot, rootErr := paths.WorktreeRoot(ctx)
443→	if rootErr != nil {
444→		repoRoot = cwd
445→	}
446→
447→	cacheDir := filepath.Join(repoRoot, ".entire", "tmp")
448→	cachePath := filepath.Join(cacheDir, sessionID+".json")
449→
450→	if err := os.MkdirAll(cacheDir, 0o750); err != nil {
451→		return "", fmt.Errorf("failed to create cache dir: %w", err)
452→	}
453→
454→	if err := os.WriteFile(cachePath, transcriptData, 0o600); err != nil {
455→		return "", fmt.Errorf("failed to write cached IDE transcript: %w", err)
456→	}
457→
458→	logging.Info(ctx, "kiro: cached IDE transcript",
459→		"ide_session", latestSession.SessionID,
460→		"our_session", sessionID,
461→		"cache_path", cachePath,
462→	)
463→
464→	return cachePath, nil
465→}
